.banner {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    right: 0;
    margin: 0;
    color:#FFF2BF;
    overflow: hidden;
    /*font-family: song;*/
}

.banner::after {
    content: '';
    position: absolute;
    width: 120%;
    left: -10%;
    top: -500px;
    font-size: 30px;
    letter-spacing: 50px;
    line-height: 70px;
    opacity:0.1;
    transform: rotate(-30deg);
    font-family: song;
    font-weight: lighter;

}

.block {
    flex: 1;
    border-radius: 20px;
    display: flex;
    align-items: center;
    padding: 10px 20px;
}

h1 {
    font-size: 80px;
    font-weight: bolder;
    font-family: song;
}

h3 {
    font-size: 24px;
    margin: -20px 20px;
    font-family: song;
}

h4 {
    font-size: 36px;
    font-family: song;
    font-weight: lighter;
    margin: 20px;
    border: solid 4px currentColor;
    display: flex;
    width: 60px;
    height: 60px;
    justify-content: center;
    align-items: center;
    border-radius: 100%;
}


.bar {
    height: 60px;
    display: flex;
    background: #fff1;
}

.bar .item {
    display: flex;
    align-items: center;
    padding: 10px 20px;
    width: 400px;
}

.bar h2.item {
    font-size: 30px;
    font-weight: bolder;
    font-family: song;
}

.gap {
    width: 100px;
}

.f1 {
    flex: 1;
}
